import {createAgent,updateAgent,giveGoal,circleClear} from './resident-ai.js?v=neighbours16';
export function tickHomeAnimal(a,dt,blocked,peers=[]){if(!a.ai){const radius=a.type==='chicken'?.28:a.type==='pig'?.65:a.type==='horse'?.85:.95,bounds=a.type==='horse'?{minX:a.x-.35,maxX:a.x+.35,minZ:-15,maxZ:-10.6}:a.type==='cow'?{minX:-17,maxX:-8,minZ:-5,maxZ:3.4}:a.type==='pig'?{minX:7,maxX:17,minZ:-5,maxZ:2.2}:{minX:11,maxX:17,minZ:10.5,maxZ:14.8};a.ai=createAgent(a.g.userData.appearanceKey||a.g.userData.name,a.g.position.x,a.g.position.z,bounds,{radius,speed:a.type==='chicken'?.5:.55});a.animationOffset=a.ai.phase;a.animationRate=a.ai.rate;
 if(!circleClear(a.ai.x,a.ai.z,radius,blocked)){for(let i=0;i<32;i++){const t=i*2.4,r=.3+Math.floor(i/8)*.4,x=a.ai.x+Math.sin(t)*r,z=a.ai.z+Math.cos(t)*r;if(x>bounds.minX&&x<bounds.maxX&&z>bounds.minZ&&z<bounds.maxZ&&circleClear(x,z,radius,blocked)){a.ai.x=x;a.ai.z=z;break;}}}}
 const brain=a.ai;if(a.behavior==='approaching'&&!a.careGoal){let goal={x:a.dest.x,z:a.dest.z};if(!giveGoal(brain,goal,blocked)){for(let i=0;i<16;i++){goal={x:a.dest.x+Math.sin(i*2.4)*1.5,z:a.dest.z+Math.cos(i*2.4)*1.5};if(giveGoal(brain,goal,blocked))break;}}a.careGoal=true;}
 let m;if(a.behavior==='eating'){a.feedRemaining-=dt;if(a.foodTarget){const target=Math.atan2(a.foodTarget.x-brain.x,a.foodTarget.z-brain.z),diff=Math.atan2(Math.sin(target-brain.heading),Math.cos(target-brain.heading));brain.heading+=Math.max(-dt*2,Math.min(dt*2,diff));}brain.phase+=dt*brain.rate;m={moved:0,mode:'graze'};if(a.feedRemaining<=0){a.behavior='idle';a.careGoal=false;brain.wait=2+brain.random()*5;}}
 else {m=updateAgent(brain,dt,blocked,peers.map(p=>p.ai).filter(Boolean));if(a.behavior==='approaching'&&!brain.route.length){a.behavior='eating';a.feedRemaining=4+brain.random()*5;}}
 a.g.position.set(brain.x,.2,brain.z);a.g.rotation.y=brain.heading;a.walkPhase+=m.moved*8;return {moved:m.moved,kind:m.moved?'walk':m.mode==='graze'?'eat':'idle'};
}
